query:
NODE VALUE `incoming` SumAgg<INT64> = 0
TABLE `results` { `id` STRING, `total` INT64 }

MATCH (`src`:`player`)-[`e`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `dst`.@`incoming` += coalesce(`e`.`degree`, 0)
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id` AS `id`, `p`.@`incoming` AS `total` INTO `results`
}

FOR `r` IN `results`
RETURN `r`.`id` AS `id`, `r`.`total` AS `total`
